#include <iostream>
#include <vector>
#include <concepts>
#include <span>
template<std::integral T> T sum(std::span<const T> values){T result{};for(T x:values)result+=x;return result;}
int main(){int n;if(!(std::cin>>n)||n<0||n>20){std::cout<<"invalid\n";return 0;}std::vector<int> a;
 for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -100||x>100){std::cout<<"invalid\n";return 0;}a.push_back(x);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::vector<long long> b(a.begin(),a.end());std::cout<<sum<int>(std::span<const int>{a})<<' '<<sum<long long>(std::span<const long long>{b})<<'\n';}

